module system
   (\syif\.tbCTRL ,
    \syif\.WEN ,
    \syif\.REN ,
    \syif\.store ,
    \syif\.addr ,
    \syif\.load ,
    \syif\.halt ,
    CLK,
    nRST,
    dbg_addr,
    dbg_data_out);
  input \syif\.tbCTRL ;
  input \syif\.WEN ;
  input \syif\.REN ;
  input [31:0]\syif\.store ;
  input [31:0]\syif\.addr ;
  output [31:0]\syif\.load ;
  output \syif\.halt ;
  input CLK;
  input nRST;
  input [13:0]dbg_addr;
  output [31:0]dbg_data_out;

  wire CLK;
  wire CPUCLK;
  wire CPUCLK_BUFG;
  wire CPUCLK_i_1_n_0;
  wire CPU_n_0;
  wire CPU_n_2;
  wire CPU_n_41;
  wire CPU_n_42;
  wire CPU_n_43;
  wire CPU_n_44;
  wire CPU_n_5;
  wire CPU_n_6;
  wire CPU_n_7;
  wire CPU_n_77;
  wire CPU_n_78;
  wire CPU_n_79;
  wire CPU_n_8;
  wire CPU_n_80;
  wire CPU_n_81;
  wire CPU_n_82;
  wire CPU_n_83;
  wire CPU_n_84;
  wire CPU_n_85;
  wire CPU_n_86;
  wire CPU_n_87;
  wire CPU_n_88;
  wire CPU_n_89;
  wire CPU_n_90;
  wire RAM_n_1;
  wire [31:0]addr;
  wire count3;
  wire [13:0]dbg_addr;
  wire [31:0]dbg_data_out;
  wire [1:0]en;
  wire nRST;
  wire \prif\.ramREN ;
  wire \prif\.ramWEN ;
  wire [31:0]\prif\.ramaddr ;
  wire [31:0]\prif\.ramstore ;
  wire [31:0]q;
  wire [31:0]\syif\.addr ;
  wire \syif\.halt ;
  wire [31:0]\syif\.load ;

  pipeline CPU
       (.CO(count3),
        .CPUCLK_BUFG(CPUCLK_BUFG),
        .D({\prif\.ramREN ,\prif\.ramWEN }),
        .E(CPU_n_2),
        .Q(en),
        .S({CPU_n_5,CPU_n_6,CPU_n_7,CPU_n_8}),
        .\addr_reg[22] ({CPU_n_84,CPU_n_85,CPU_n_86,CPU_n_87}),
        .\addr_reg[31] ({CPU_n_77,CPU_n_78,CPU_n_79}),
        .\addr_reg[31]_0 ({CPU_n_88,CPU_n_89,CPU_n_90}),
        .\addr_reg[9] ({CPU_n_41,CPU_n_42,CPU_n_43,CPU_n_44}),
        .\addr_reg[9]_0 ({CPU_n_80,CPU_n_81,CPU_n_82,CPU_n_83}),
        .auto_nRST_reg(CPU_n_0),
        .\instruction_reg[18]_rep (RAM_n_1),
        .nRST(nRST),
        .\prif\.ramaddr (\prif\.ramaddr ),
        .q(q),
        .\ramif\.ramstore (\prif\.ramstore ),
        .rstate3_carry__1(addr),
        .state_reg(\syif\.halt ),
        .\syif\.addr (\syif\.addr [15:0]));
  BUFG CPUCLK_BUFG_inst
       (.I(CPUCLK),
        .O(CPUCLK_BUFG));
  LUT1 #(
    .INIT(2'h1)) 
    CPUCLK_i_1
       (.I0(CPUCLK),
        .O(CPUCLK_i_1_n_0));
  FDCE #(
    .INIT(1'b0)) 
    CPUCLK_reg
       (.C(CLK),
        .CE(1'b1),
        .CLR(CPU_n_0),
        .D(CPUCLK_i_1_n_0),
        .Q(CPUCLK));
  ram RAM
